export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: (QuoteStep | ClaimStep)[];
}

export type Result = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const COMPONENT_BASE_PREMIUM = 25;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: COMPONENT_BASE_PREMIUM,
  moonstone: COMPONENT_BASE_PREMIUM,
};
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

function policyBasePremium(items: Item[]): number {
  return items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
}

function quotePremium(items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): Result[] {
  return scenario.steps.map((step) => ({ premium: quotePremium((step as QuoteStep).items) }));
}
import { describe, expect, it } from "vitest";
import { runScenario, type Item, type Scenario } from "./claimOffice.js";

const newcomer = { yearsWithMHPCO: 0 };

const runes = (count: number): Item[] => Array.from({ length: count }, () => ({ type: "rune" }));
const moonstones = (count: number): Item[] => Array.from({ length: count }, () => ({ type: "moonstone" }));

function premiumFor(customer: Scenario["customer"], items: Item[]): number {
  const [result] = runScenario({ customer, steps: [{ op: "quote", items }] });
  return "premium" in result ? result.premium : Number.NaN;
}

describe("quote", () => {
  it("empty item list -> premium 5 G (only the processing fee)", () => {
    expect(premiumFor(newcomer, [])).toBe(5);
  });
  it("newcomer, plain steel sword (enchantment 3) -> 100 base + 10 first insurance + 5 fee = 115 G", () => {
    const sword = { type: "sword", material: "steel", enchantment: 3, cursed: false };
    expect(premiumFor(newcomer, [sword])).toBe(115);
  });
  it("newcomer, plain amulet -> 60 + 6 + 5 = 71 G", () => {
    expect(premiumFor(newcomer, [{ type: "amulet" }])).toBe(71);
  });
  it("newcomer, plain staff -> 80 + 8 + 5 = 93 G", () => {
    expect(premiumFor(newcomer, [{ type: "staff" }])).toBe(93);
  });
  it("newcomer, plain potion -> 40 + 4 + 5 = 49 G", () => {
    expect(premiumFor(newcomer, [{ type: "potion" }])).toBe(49);
  });
  it("newcomer, 1 rune -> 25 + 2.5 + 5 = 32.5 -> rounded up to 33 G", () => {
    expect(premiumFor(newcomer, [{ type: "rune" }])).toBe(33);
  });
  it("newcomer, 1 moonstone -> 25 base like any component -> 33 G", () => {
    expect(premiumFor(newcomer, [{ type: "moonstone" }])).toBe(33);
  });
  it("2 runes -> base 50 G -> 50 + 5 + 5 = 60 G", () => {
    expect(premiumFor(newcomer, runes(2))).toBe(60);
  });
  it.todo("3 runes -> block base 60 G -> 60 + 6 + 5 = 71 G");
  it.todo("4 runes -> base 100 G (no block, block requires exactly 3) -> 100 + 10 + 5 = 115 G");
  it.todo("7 runes -> base 175 G -> 175 + 17.5 + 5 = 197.5 -> 198 G");
  it.todo("2 runes + 1 moonstone -> base 75 G (no block: different types) -> 75 + 7.5 + 5 = 87.5 -> 88 G");
  it.todo("3 runes + 3 moonstones -> base 120 G (two blocks) -> 120 + 12 + 5 = 137 G");
  it.todo("newcomer, cursed steel sword (enchantment 3) -> 100 + 50 curse + 10 first + 5 = 165 G");
  it.todo("sword with enchantment 4, not cursed -> no high-enchantment surcharge -> 115 G");
  it.todo("sword with exactly enchantment 5 -> 30 % surcharge -> 100 + 30 + 10 + 5 = 145 G");
  it.todo("cursed sword with exactly enchantment 5 -> both surcharges -> 100 + 50 + 30 + 10 + 5 = 195 G");
  it.todo("cursed sword with enchantment 4 -> only curse surcharge -> 165 G");
  it.todo("cursed sword + plain amulet -> curse applies to sword only: 160 + 50 + 16 first + 5 = 231 G");
  it.todo("customer with 1 year, plain sword -> no loyalty discount -> 115 G");
  it.todo("customer with exactly 2 years, plain sword -> 20 % loyalty discount on policy base: 100 - 20 + 10 + 5 = 95 G");
  it.todo("second quote in scenario gets 15 % follow-up discount on policy base: newcomer plain sword twice -> 115 G, then 100 + 10 - 15 + 5 = 100 G");
  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 -> 160 G (first insurance still applies)");
  it.todo("2 years, cursed sword enchantment 5 + rune -> 125 + 50 + 30 - 25 + 12.5 + 5 = 197.5 -> rounded up to 198 G");
});

describe("claim", () => {
  it.todo("regular steel sword (enchantment 3), damage 500 G -> payout 400 G, remainingCap 1600 G");
  it.todo("rune (insurance value 250 G), damage 200 G -> payout 100 G, remainingCap 400 G");
  it.todo("amulet damage 200 G -> payout 100 G, remainingCap 1100 G (cap = 2 x 600)");
  it.todo("staff damage 200 G -> payout 100 G, remainingCap 1500 G (cap = 2 x 800)");
  it.todo("potion damage 200 G -> payout 100 G, remainingCap 700 G (cap = 2 x 400)");
  it.todo("moonstone damage 200 G -> payout 100 G, remainingCap 400 G (cap = 2 x 250)");
  it.todo("steel sword enchantment 9, damage 1000 G -> 50 % then deductible -> payout 400 G");
  it.todo("dragon sword enchantment 9, damage 1000 G -> 50 % rule wins -> payout 400 G");
  it.todo("dragon sword exactly enchantment 8, damage 1000 G -> payout 400 G");
  it.todo("dragon sword enchantment 5, damage 800 G -> full reimbursement -> payout 700 G");
  it.todo("sword enchantment 8, damage 901 G -> 450.5 - 100 = 350.5 -> rounded down to 350 G");
  it.todo("sword (500 G) and amulet (300 G) damaged in one event -> deductible per item -> payout 600 G, remainingCap 2600 G");
  it.todo("two swords insured -> cap 4000 G; both damaged 500 G each -> payout 800 G, remainingCap 3200 G");
  it.todo("cursed sword -> cap 2000 G based on unmodified insurance value: damage 500 G -> remainingCap 1600 G");
  it.todo("sword + 3 runes (block) -> insurance sum 1750 G, cap 3500 G: sword damage 500 G -> remainingCap 3100 G");
  it.todo("sword, two successive claims of 1500 G -> payouts 1400 G (cap 600) then 600 G (cap 0)");
  it.todo("claim references the policy by its quote step index when several policies exist");
});

describe("rejections (throws Error with a description)", () => {
  it.todo("quote with unknown item type 'broomstick' throws");
  it.todo("claim damaging an amulet when only a sword is insured throws");
  it.todo("claim damaging an unknown item type throws");
  it.todo("claim with two sword damages but only one sword insured throws");
  it.todo("claim with damage amount -200 throws");
});
# MHPCO Claim Office Kata

## Setting

You are building the policy management system for the **Most Honorable
Privileged Claims Office for Magical Risks and Cursed Items** (MHPCO),
an old-fashioned insurance institution that covers magical items —
swords, amulets, staves, potions, and components such as runes and
moonstones. The MHPCO is bureaucratic, slightly stingy, and proud of
its venerable traditions.

## Feature

The system supports two operations: **quote** computes the premium for
a list of items a customer wishes to insure, and **claim** processes a
damage report against an existing policy.

## Rules

### Item values and base premiums

Each main item has an insurance value and a base premium according to
the MHPCO price list:

- Sword: 1000 G insurance value, 100 G base premium
- Amulet: 600 G / 60 G
- Staff: 800 G / 80 G
- Potion: 400 G / 40 G

Components — for example runes and moonstones — are insured at 250 G
each, with a base premium of 25 G per component. A building block of
3 alike components is offered at a special base premium of 60 G.

### Premium modifiers

- Cursed items add a 50 % risk surcharge.
- Highly enchanted items (enchantment level ≥ 5) add a 30 % risk
  surcharge.
- Long-standing customers (≥ 2 years of business with MHPCO) receive a
  20 % loyalty discount.
- A first insurance carries a 10 % initial assessment surcharge.
- Customers receive a 15 % discount on each contract after their first.
- A 5 G processing fee is added to every premium.

All amounts are rounded to whole G in the MHPCO's favor.

### Claim processing

A deductible of 100 G applies per damage event. The total payout per
policy is capped at twice the insurance sum.

- Damage to items with enchantment level ≥ 8 is reimbursed at 50 % of
  the damage amount.
- Damage to items made of dragon material is fully reimbursed.

## Examples

The examples below illustrate single rules in isolation. Values shown
are base premiums or raw payout amounts before integration with other
modifiers, unless stated otherwise.

